//! Differential test: the Rust `Minter` port must match the windv2 Solidity `Minter` exactly.
//!
//! Vectors are generated by `diff-tests/` (Foundry) from the real `Minter.sol`, deployed with
//! mocks for wind, ve, voter, epoch governor and rewards distributor:
//! `cd diff-tests && forge test --match-test testGenerateMinter`
//!
//! The file is replayed in order on a single `Minter`. Every line carries its inputs, the
//! Solidity outcome (`ok`, `noop`, `err` with a reason) and the full state after the call, and
//! every line is checked against the Rust port.

use std::collections::BTreeMap;
use std::fs;
use std::path::PathBuf;

use windswap_engine::minter::{EpochEmission, Minter, ProposalState, TAIL_START};
use windswap_engine::{MathError, U256};

fn read_vectors() -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../diff-tests/vectors")
        .join("minter.txt");
    fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()))
}

fn u(s: &str) -> U256 {
    s.parse().unwrap()
}

/// `weekly,tailEmissionRate,teamRate,activePeriod,epochCount,nudgedThisPeriod`, as the Solidity
/// test logs it (decimal values, `1`/`0` for the flag).
fn state(m: &Minter) -> String {
    format!(
        "{},{},{},{},{},{}",
        m.weekly,
        m.tail_emission_rate,
        m.team_rate,
        m.active_period,
        m.epoch_count,
        u8::from(m.proposals.contains(&m.active_period))
    )
}

/// Whether a Rust error matches the reason the Solidity call reverted with.
/// `Panic17` is Solidity's arithmetic panic (overflow or underflow). It cannot be told apart from
/// the revert data, so either Rust error is accepted.
fn reason_matches(reason: &str, err: MathError) -> bool {
    match reason {
        "Panic17" => matches!(err, MathError::Overflow | MathError::Underflow),
        "Panic18" => err == MathError::DivisionByZero,
        "TailEmissionsInactive" => err == MathError::TailEmissionsInactive,
        "AlreadyNudged" => err == MathError::AlreadyNudged,
        "RateTooHigh" => err == MathError::RateTooHigh,
        _ => false,
    }
}

/// `IEpochGovernor.ProposalState` from its Solidity index.
fn proposal_state(v: u8) -> ProposalState {
    match v {
        0 => ProposalState::Pending,
        1 => ProposalState::Active,
        2 => ProposalState::Canceled,
        3 => ProposalState::Defeated,
        4 => ProposalState::Succeeded,
        5 => ProposalState::Queued,
        6 => ProposalState::Expired,
        7 => ProposalState::Executed,
        _ => panic!("bad proposal state {v}"),
    }
}

#[derive(Default)]
struct Tally(BTreeMap<String, usize>);

impl Tally {
    fn bump(&mut self, key: &str) {
        *self.0.entry(key.to_owned()).or_default() += 1;
    }

    fn get(&self, key: &str) -> usize {
        self.0.get(key).copied().unwrap_or(0)
    }
}

/// Replays `minter.txt`. Each line's Solidity outcome and post-state must match the Rust port.
#[test]
fn minter_stateful_replay() {
    let text = read_vectors();
    let mut lines = text.lines().filter(|l| !l.is_empty());

    let init: Vec<&str> = lines
        .next()
        .expect("empty vector file")
        .split('|')
        .collect();
    assert_eq!(init[0], "init");
    let mut m = Minter::new(init[1].parse().unwrap());
    assert_eq!(state(&m), init[2], "init");

    let tail_start = U256::from(TAIL_START);
    let mut t = Tally::default();

    for line in lines {
        let f: Vec<&str> = line.split('|').collect();
        let post = *f.last().unwrap();
        match f[0] {
            "update" => {
                let tail_before = m.weekly < tail_start;
                let res = m.update_period(f[1].parse().unwrap(), u(f[2]), u(f[3]), u(f[4]));
                match f[5] {
                    "noop" => {
                        assert_eq!(res, Ok(None), "{line}");
                        t.bump("update.noop");
                    }
                    "ok" => {
                        let exp = EpochEmission {
                            emission: u(f[6]),
                            growth: u(f[7]),
                            team: u(f[8]),
                            mint_required: u(f[9]),
                        };
                        assert_eq!(res, Ok(Some(exp)), "{line}");
                        t.bump(if tail_before {
                            "update.ok.tail"
                        } else {
                            "update.ok.normal"
                        });
                    }
                    "err" => {
                        let e = res.expect_err(line);
                        assert!(reason_matches(f[6], e), "{line}: Rust returned {e:?}");
                        t.bump("update.err");
                    }
                    other => panic!("bad update status {other}: {line}"),
                }
            }
            "nudge" => {
                let res = m.nudge(proposal_state(f[1].parse().unwrap()));
                match f[2] {
                    "ok" => {
                        assert_eq!(res, Ok(()), "{line}");
                        t.bump("nudge.ok");
                    }
                    "err" => {
                        let e = res.expect_err(line);
                        assert!(reason_matches(f[3], e), "{line}: Rust returned {e:?}");
                        t.bump(&format!("nudge.err.{}", f[3]));
                    }
                    other => panic!("bad nudge status {other}: {line}"),
                }
            }
            "teamRate" => {
                let res = m.set_team_rate(u(f[1]));
                match f[2] {
                    "ok" => {
                        assert_eq!(res, Ok(()), "{line}");
                        t.bump("teamRate.ok");
                    }
                    "err" => {
                        let e = res.expect_err(line);
                        assert!(reason_matches(f[3], e), "{line}: Rust returned {e:?}");
                        t.bump(&format!("teamRate.err.{}", f[3]));
                    }
                    other => panic!("bad teamRate status {other}: {line}"),
                }
            }
            "calc" => {
                let res = m.calculate_growth(u(f[1]), u(f[2]), u(f[3]));
                match f[4] {
                    "ok" => {
                        assert_eq!(res, Ok(u(f[5])), "{line}");
                        t.bump("calc.ok");
                    }
                    "err" => {
                        let e = res.expect_err(line);
                        assert!(reason_matches(f[5], e), "{line}: Rust returned {e:?}");
                        t.bump("calc.err");
                    }
                    other => panic!("bad calc status {other}: {line}"),
                }
                // calc is a view: the state is unchanged, so only the outputs are checked above.
                continue;
            }
            other => panic!("unknown op {other}: {line}"),
        }
        assert_eq!(state(&m), post, "state after {line}");
    }

    eprintln!("minter vector counts: {:?}", t.0);
    assert!(t.get("update.ok.normal") >= 50, "too few normal epochs");
    assert!(t.get("update.ok.tail") >= 100, "too few tail epochs");
    assert!(t.get("update.noop") > 0);
    assert!(t.get("update.err") > 0);
    assert!(t.get("nudge.ok") > 0);
    assert!(t.get("nudge.err.TailEmissionsInactive") > 0);
    assert!(t.get("nudge.err.AlreadyNudged") > 0);
    assert!(t.get("teamRate.ok") > 0);
    assert!(t.get("teamRate.err.RateTooHigh") > 0);
    assert!(t.get("calc.ok") > 0);
    assert!(t.get("calc.err") > 0);
}
